use vstd::prelude::*;

verus! {

fn rotate_right(list: &Vec<u32>, n: usize) -> (new_list: Vec<u32>)
    requires
        list.len() > 0,
    ensures
        new_list.len() == list.len(),
        // Functional specification: right-rotation by r = n % len
        forall|i: int|
            0 <= i < new_list.len() ==> {
                let len: int = list.len() as int;
                let r: int = (n % list.len()) as int;
                new_list[i] == list[((i - r + len) % len)]
            },
{
    let len = list.len();
    debug_assert!(len > 0);

    let r = n % len;
    let s = len - r;

    let mut new_list = Vec::with_capacity(len);

    new_list.extend_from_slice(&list[s..len]);
    new_list.extend_from_slice(&list[0..s]);

    // Postcondition helpers (not changing behavior)
    assert(new_list.len() == len);

    new_list
}

} // verus!